   159→// gatherCurrentSessionDetails attempts to get transcript info for sessions without checkpoints.
   160→// This handles strategies like shadow where active sessions may not have checkpoint commits.
   161→func gatherCurrentSessionDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   162→	// Try to get transcript via GetSessionContext which reads from metadata branch
   163→	// For shadow, we can read the transcript from the same location pattern
   164→	contextContent := strat.GetSessionContext(session.ID)
   165→	if contextContent == "" {
   166→		return nil
   167→	}
   168→
   169→	// Parse the context.md to extract the last prompt/summary
   170→	// Context.md typically has sections like "# Prompt\n...\n## Summary\n..."
   171→	detail := checkpointDetail{
   172→		Index:     1,
   173→		Timestamp: session.StartTime,
   174→		Message:   "Current session",
   175→	}
   176→
   177→	// Try to extract prompt and summary from context.md
   178→	lines := strings.Split(contextContent, "\n")
   179→	var inPrompt, inSummary bool
   180→	var promptLines, summaryLines []string
   181→
   182→	for _, line := range lines {
   183→		trimmed := strings.TrimSpace(line)
   184→		if strings.HasPrefix(trimmed, "# ") && strings.Contains(strings.ToLower(trimmed), "prompt") {
   185→			inPrompt = true
   186→			inSummary = false
   187→			continue
   188→		}
   189→		if strings.HasPrefix(trimmed, "## ") && strings.Contains(strings.ToLower(trimmed), "summary") {
   190→			inPrompt = false
   191→			inSummary = true
   192→			continue
   193→		}
   194→		if strings.HasPrefix(trimmed, "## ") || strings.HasPrefix(trimmed, "# ") {
   195→			inPrompt = false
   196→			inSummary = false
   197→			continue
   198→		}
   199→
   200→		if inPrompt {
   201→			promptLines = append(promptLines, line)
   202→		} else if inSummary {
   203→			summaryLines = append(summaryLines, line)
   204→		}
   205→	}
