   208→	if len(promptLines) > 0 {
   209→		inter.Prompt = strings.TrimSpace(strings.Join(promptLines, "\n"))
   210→	}
   211→	if len(summaryLines) > 0 {
   212→		inter.Responses = []string{strings.TrimSpace(strings.Join(summaryLines, "\n"))}
   213→	}
   214→
   215→	// If we couldn't parse structured content, show the raw context
   216→	if inter.Prompt == "" && len(inter.Responses) == 0 {
   217→		inter.Responses = []string{contextContent}
   218→	}
   219→
   220→	if inter.Prompt != "" || len(inter.Responses) > 0 {
