   227→// gatherCheckpointDetails extracts detailed information for each checkpoint.
   228→// Checkpoints come in newest-first order, but we number them oldest=1, newest=N.
   229→func gatherCheckpointDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   230→	details := make([]checkpointDetail, 0, len(session.Checkpoints))
   231→	total := len(session.Checkpoints)
   232→
   233→	for i, cp := range session.Checkpoints {
   234→		detail := checkpointDetail{
   235→			Index:            total - i, // Reverse numbering: oldest=1, newest=N
   236→			Timestamp:        cp.Timestamp,
   237→			IsTaskCheckpoint: cp.IsTaskCheckpoint,
   238→			Message:          cp.Message,
   239→		}
   240→
   241→		// Use checkpoint ID for display (truncate long IDs)
   242→		detail.ShortID = cp.CheckpointID
   243→		if len(detail.ShortID) > 12 {
   244→			detail.ShortID = detail.ShortID[:12]
   245→		}
   246→
   247→		// Try to get transcript for this checkpoint
   248→		transcriptContent, err := strat.GetCheckpointLog(cp)
   249→		if err == nil {
   250→			transcript, parseErr := parseTranscriptFromBytes(transcriptContent)
   251→			if parseErr == nil {
   252→				// Extract all prompt/response pairs from the transcript
   253→				pairs := ExtractAllPromptResponses(transcript)
   254→				for _, pair := range pairs {
   255→					detail.Interactions = append(detail.Interactions, interaction(pair))
   256→				}
   257→
   258→				// Aggregate all files for the checkpoint
   259→				fileSet := make(map[string]bool)
   260→				for _, pair := range pairs {
   261→					for _, f := range pair.Files {
   262→						if !fileSet[f] {
   263→							fileSet[f] = true
   264→							detail.Files = append(detail.Files, f)
   265→						}
   266→					}
   267→				}
   268→			}
   269→		}
   270→
   271→		details = append(details, detail)
   272→	}
   273→
   274→	return details
   275→}
