   277→// runExplainCommit explains a specific commit.
   278→func runExplainCommit(w io.Writer, commitRef string) error {
   279→	repo, err := openRepository()
   280→	if err != nil {
   281→		return fmt.Errorf("not a git repository: %w", err)
   282→	}
   283→
   284→	// Resolve the commit reference
   285→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
   286→	if err != nil {
   287→		return fmt.Errorf("commit not found: %s", commitRef)
   288→	}
   289→
   290→	commit, err := repo.CommitObject(*hash)
   291→	if err != nil {
   292→		return fmt.Errorf("failed to get commit: %w", err)
   293→	}
   294→
   295→	// Get files changed in this commit (diff from parent to current)
   296→	var files []string
   297→	commitTree, err := commit.Tree()
   298→	if err == nil && commit.NumParents() > 0 {
   299→		parent, parentErr := commit.Parent(0)
   300→		if parentErr == nil {
   301→			parentTree, treeErr := parent.Tree()
   302→			if treeErr == nil {
   303→				// Diff from parent to current commit to show what changed
   304→				changes, diffErr := parentTree.Diff(commitTree)
   305→				if diffErr == nil {
   306→					for _, change := range changes {
   307→						name := change.To.Name
   308→						if name == "" {
   309→							name = change.From.Name
   310→						}
   311→						files = append(files, name)
   312→					}
   313→				}
   314→			}
   315→		}
   316→	}
   317→
   318→	// Check for Entire metadata
   319→	metadataDir, hasMetadata := paths.ParseMetadataTrailer(commit.Message)
   320→	sessionID, hasSession := paths.ParseSessionTrailer(commit.Message)
   321→
   322→	// If no session trailer, try to extract from metadata path.
   323→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
   324→	// by both the rewind and explain commands for parsing metadata paths.
   325→	if !hasSession && hasMetadata {
   326→		sessionID = extractSessionIDFromMetadata(metadataDir)
   327→		hasSession = sessionID != ""
   328→	}
