   338→		SHA:       fullSHA,
   339→		ShortSHA:  shortSHA,
   340→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
   341→		Author:    commit.Author.Name,
   342→		Email:     commit.Author.Email,
   343→		Date:      commit.Author.When,
   344→		Files:     files,
   345→		HasEntire: hasMetadata || hasSession,
