   473→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
   474→func outputWithPager(w io.Writer, content string) {
   475→	// Check if we're writing to stdout and it's a terminal
   476→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
   477→		// Get terminal height
   478→		_, height, err := term.GetSize(int(f.Fd()))
   479→		if err != nil {
   480→			height = 24 // Default fallback
   481→		}
   482→
   483→		// Count lines in content
   484→		lineCount := strings.Count(content, "\n")
   485→
   486→		// Use pager if content exceeds terminal height
   487→		if lineCount > height-2 {
   488→			pager := os.Getenv("PAGER")
   489→			if pager == "" {
   490→				pager = "less"
   491→			}
   492→
   493→			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
   494→			cmd.Stdin = strings.NewReader(content)
   495→			cmd.Stdout = f
   496→			cmd.Stderr = os.Stderr
   497→
   498→			if err := cmd.Run(); err != nil {
   499→				// Fallback to direct output if pager fails
   500→				fmt.Fprint(w, content)
   501→			}
   502→			return
   503→		}
   504→	}
   505→
   506→	// Direct output for non-terminal or short content
   507→	fmt.Fprint(w, content)
   508→}
